const body = $input.first().json.body || {};

// Validate required fields
const message = body.message;
const guildId = body.guild_id;
const userId = body.user_id;
const availableSubjects = body.available_subjects;
const currentSubjectSlug = body.current_subject_slug || null;
const confidenceThreshold = body.confidence_threshold || 0.6;

const errors = [];

if (!message || typeof message !== 'string' || message.trim().length === 0) {
  errors.push('message (non-empty string) is required');
}
if (!guildId || typeof guildId !== 'string') {
  errors.push('guild_id (string) is required');
}
if (!userId || typeof userId !== 'string') {
  errors.push('user_id (string) is required');
}
if (!availableSubjects || !Array.isArray(availableSubjects) || availableSubjects.length === 0) {
  errors.push('available_subjects (non-empty array) is required');
}

if (errors.length > 0) {
  return {
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  };
}

// Validate available_subjects contains only strings
const validSubjects = availableSubjects.every(s => typeof s === 'string' && s.trim().length > 0);
if (!validSubjects) {
  return {
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'available_subjects must contain non-empty strings only',
        status: 'BAD_REQUEST'
      }
    }
  };
}

// If current_subject_slug provided, verify it's in available_subjects
if (currentSubjectSlug && !availableSubjects.includes(currentSubjectSlug)) {
  return {
    json: {
      valid: false,
      error: {
        code: 400,
        message: `current_subject_slug '${currentSubjectSlug}' is not in available_subjects`,
        status: 'BAD_REQUEST'
      }
    }
  };
}

return {
  json: {
    valid: true,
    startTime: Date.now(),
    message: message.trim(),
    guild_id: guildId,
    user_id: userId,
    available_subjects: availableSubjects,
    current_subject_slug: currentSubjectSlug,
    confidence_threshold: Math.min(1, Math.max(0, confidenceThreshold))
  }
};

