const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const statusCode = input.statusCode || 200;
const startTime = prevData.startTime || Date.now();

// Extract LLM response content (for _trace)
const llmContent = input.body?.content || [];
const usage = input.body?.usage || {};
const llmModel = input.body?.model || 'claude-3-haiku-20240307';

// Handle LLM API error
if (statusCode >= 400) {
  const errorMessage = input.body?.error?.message || 'LLM API error';

  // If we have a fallback subject, use it
  if (prevData.current_subject_slug) {
    return {
      json: {
        success: true,
        data: {
          detected_subject: prevData.current_subject_slug,
          confidence: 0,
          reason: `Erreur API LLM: ${errorMessage}. Fallback vers matiere actuelle.`,
          fallback_used: true,
          current_subject: prevData.current_subject_slug
        },
        _trace: {
          llm_response: [{ type: 'error', error: errorMessage }],
          model: llmModel,
          tokens: { input: 0, output: 0 },
          latency_ms: Date.now() - startTime
        }
      }
    };
  }

  return {
    json: {
      success: false,
      error: {
        code: statusCode,
        message: errorMessage,
        status: 'LLM_ERROR'
      },
      _trace: {
        llm_response: [{ type: 'error', error: errorMessage }],
        model: llmModel,
        tokens: { input: 0, output: 0 },
        latency_ms: Date.now() - startTime
      }
    }
  };
}

// Extract text content for parsing
const content = llmContent[0]?.text || '';

// Parse JSON from LLM response
let parsed;
try {
  // Try to find JSON in response (handle markdown code blocks)
  let jsonStr = content;
  const jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1].trim();
  } else {
    // Try to find raw JSON object
    const rawMatch = content.match(/\{[\s\S]*\}/);
    if (rawMatch) {
      jsonStr = rawMatch[0];
    }
  }

  parsed = JSON.parse(jsonStr);
} catch (e) {
  // Parse error - use fallback if available
  if (prevData.current_subject_slug) {
    return {
      json: {
        success: true,
        data: {
          detected_subject: prevData.current_subject_slug,
          confidence: 0,
          reason: `Erreur de parsing LLM. Fallback vers matiere actuelle.`,
          fallback_used: true,
          current_subject: prevData.current_subject_slug
        },
        _trace: {
          llm_response: llmContent,
          model: llmModel,
          tokens: { input: usage.input_tokens || 0, output: usage.output_tokens || 0 },
          latency_ms: Date.now() - startTime
        }
      }
    };
  }

  return {
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to parse LLM response: ' + e.message,
        status: 'PARSE_ERROR'
      },
      _trace: {
        llm_response: llmContent,
        model: llmModel,
        tokens: { input: usage.input_tokens || 0, output: usage.output_tokens || 0 },
        latency_ms: Date.now() - startTime
      }
    }
  };
}

// Validate parsed response
const detectedSubject = parsed.subject;
const confidence = typeof parsed.confidence === 'number' ? Math.min(1, Math.max(0, parsed.confidence)) : 0;
const reason = parsed.reason || 'Aucune raison fournie';

// Check if detected subject is valid
const isValidSubject = prevData.available_subjects.includes(detectedSubject);

// Determine if we should use fallback
const useFallback = !isValidSubject || confidence < prevData.confidence_threshold;
const finalSubject = useFallback && prevData.current_subject_slug 
  ? prevData.current_subject_slug 
  : (isValidSubject ? detectedSubject : prevData.available_subjects[0]);

return {
  json: {
    success: true,
    data: {
      detected_subject: finalSubject,
      confidence: useFallback ? 0 : confidence,
      reason: useFallback 
        ? (isValidSubject ? `Confiance (${(confidence * 100).toFixed(0)}%) inferieure au seuil (${(prevData.confidence_threshold * 100).toFixed(0)}%). Fallback vers matiere actuelle.` : `Matiere '${detectedSubject}' non disponible. Fallback vers matiere actuelle.`)
        : reason,
      fallback_used: useFallback,
      current_subject: prevData.current_subject_slug,
      llm_detection: {
        subject: detectedSubject,
        confidence: confidence,
        reason: reason
      }
    },
    _trace: {
      llm_response: llmContent,
      model: llmModel,
      tokens: { 
        input: usage.input_tokens || 0, 
        output: usage.output_tokens || 0 
      },
      latency_ms: Date.now() - startTime
    }
  }
};

